import sys
def tdiv(a, b):
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b >= 0) else -q

def eval_rpn(tokens):
    toks = list(tokens)
    while len(toks) > 1:
        for i in range(2, len(toks)):
            if toks[i] in '+-*/':
                a, b = int(toks[i - 2]), int(toks[i - 1])
                op = toks[i]
                if op == '+':
                    r = a + b
                elif op == '-':
                    r = a - b
                elif op == '*':
                    r = a * b
                else:
                    r = tdiv(a, b)
                toks[i - 2:i + 1] = [str(r)]
                break
    return int(toks[0])


