def eval_rpn(tokens):
    stack = []
    for t in tokens:
        if t == '+':
            stack.append(stack.pop() + stack.pop())
        elif t == '-':
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif t == '*':
            stack.append(stack.pop() * stack.pop())
        elif t == '/':
            b = stack.pop()
            a = stack.pop()
            stack.append(tdiv(a, b))
        else:
            stack.append(int(t))
    return stack[0]


